window.DOCTIZE_SEARCH_INDEX = {"records":[{"url":"quick-start/quick-start.html","title":"Quick start","section":"Quick start","heading":"","text":"This tutorial takes about five minutes. You will add Acme Cache to a project, build a cache, and watch it evict.","keywords":"tutorial hello world getting started","kind":"page","area":"guides"},{"url":"quick-start/quick-start.html#1.-add-the-dependency","title":"Quick start","section":"Quick start","heading":"1. Add the dependency","text":"dependencies { implementation 'dev.example:acme-cache:1.2.0' } dependencies { implementation(\"dev.example:acme-cache:1.2.0\") } <dependency> <groupId>dev.example<\/groupId> <artifactId>acme-cache<\/artifactId> <version>1.2.0<\/version> <\/dependency>","keywords":"","kind":"section","area":"guides"},{"url":"quick-start/quick-start.html#2.-build-a-cache","title":"Quick start","section":"Quick start","heading":"2. Build a cache","text":"Everything starts at Cache.builder(): import dev.example.cache.Cache; import dev.example.cache.EvictionPolicy; public class Main { public static void main(String[] args) { Cache<String, Integer> lengths = Cache.<String, Integer>builder() .maximumSize(2) .evictionPolicy(EvictionPolicy.LRU) .recordStats() .build(); lengths.put(\"one\", 3); lengths.put(\"two\", 3); lengths.get(\"one\"); // \"one\" is now the most recently used lengths.put(\"three\", 5); // evicts \"two\" System.out.println(lengths.get(\"two\").isPresent()); // false System.out.println(lengths.stats()); } }","keywords":"","kind":"section","area":"guides"},{"url":"quick-start/quick-start.html#3.-load-values-on-demand","title":"Quick start","section":"Quick start","heading":"3. Load values on demand","text":"Most caches are filled lazily. Cache.getOrLoad(Object, java.util.function.Function) loads a value once and serves it from memory afterwards: String page = pages.getOrLoad(url, httpClient::fetch); The loader must not return null. A null result raises a CacheLoadException.","keywords":"","kind":"section","area":"guides"},{"url":"quick-start/quick-start.html#next-steps","title":"Quick start","section":"Quick start","heading":"Next steps","text":"Read Installation for supported Java versions. Learn how eviction policies differ. Browse the CacheBuilder reference for every setting.","keywords":"","kind":"section","area":"guides"},{"url":"setup/installation.html","title":"Installation","section":"Setup","heading":"","text":"Requirement Version Java 17 or newer Build tool Gradle 7+ or Maven 3.8+ Runtime dependencies none","keywords":"","kind":"page","area":"guides"},{"url":"setup/installation.html#requirements","title":"Installation","section":"Setup","heading":"Requirements","text":"Requirement Version Java 17 or newer Build tool Gradle 7+ or Maven 3.8+ Runtime dependencies none","keywords":"","kind":"section","area":"guides"},{"url":"setup/installation.html#add-the-library","title":"Installation","section":"Setup","heading":"Add the library","text":"implementation 'dev.example:acme-cache:1.2.0' <dependency> <groupId>dev.example<\/groupId> <artifactId>acme-cache<\/artifactId> <version>1.2.0<\/version> <\/dependency> Not sure which version is the latest? The badge in the top bar of this site always shows the version these docs describe.","keywords":"","kind":"section","area":"guides"},{"url":"setup/installation.html#verify-the-installation","title":"Installation","section":"Setup","heading":"Verify the installation","text":"System.out.println(Cache.builder().build().size()); // 0 If this prints 0, you are ready for the Quick start.","keywords":"","kind":"section","area":"guides"},{"url":"setup/configuration.html","title":"Configuration","section":"Setup","heading":"","text":"Acme Cache is configured in code, through CacheBuilder. There are no configuration files and no system properties.","keywords":"","kind":"page","area":"guides"},{"url":"setup/configuration.html#settings-at-a-glance","title":"Configuration","section":"Setup","heading":"Settings at a glance","text":"Method Default Effect CacheBuilder.maximumSize(long) unbounded Caps the number of entries CacheBuilder.expireAfterWrite(java.time.Duration) never Expires entries after a time to live CacheBuilder.evictionPolicy(EvictionPolicy) EvictionPolicy.LRU Chooses the entry to evict CacheBuilder.recordStats() off Enables Cache.stats()","keywords":"","kind":"section","area":"guides"},{"url":"setup/configuration.html#sizing-a-cache","title":"Configuration","section":"Setup","heading":"Sizing a cache","text":"Choose the size from the memory you can spare, not from the number of entries you hope to store: Estimate the average size of one entry. Multiply by the number of entries you want to keep. Add 30% for overhead. Set a maximum size Record statistics in production for a week Tune the eviction policy based on the hit rate","keywords":"","kind":"section","area":"guides"},{"url":"guides/choosing-an-eviction-policy.html","title":"Choosing an eviction policy","section":"Guides","heading":"","text":"A bounded cache must decide what to throw away when it is full. Acme Cache offers three policies, selected with dev.example.cache.CacheBuilder.evictionPolicy. Policy Evicts Best for EvictionPolicy.LRU the entry not used for the longest time most workloads EvictionPolicy.LFU the entry used least often stable hot sets with bursts of one-off reads EvictionPolicy.FIFO the oldest entry data with a natural time-to-live","keywords":"lru lfu fifo","kind":"page","area":"guides"},{"url":"guides/choosing-an-eviction-policy.html#how-to-decide","title":"Choosing an eviction policy","section":"Guides","heading":"How to decide","text":"Start with LRU. Record statistics and look at the hit rate: var cache = Cache.<String, Page>builder().maximumSize(1_000).recordStats().build(); // ... run your workload ... System.out.printf(\"hit rate: %.1f%%%n\", cache.stats().hitRate() * 100); If a full table scan pushes the hot entries out, try LFU.","keywords":"","kind":"section","area":"guides"},{"url":"guides/choosing-an-eviction-policy.html#expiry-is-independent","title":"Choosing an eviction policy","section":"Guides","heading":"Expiry is independent","text":"Expiry (time to live) is checked on every read and works with every policy.","keywords":"","kind":"section","area":"guides"},{"url":"guides/testing.html","title":"Testing code that uses a cache","section":"Guides","heading":"","text":"Caches make tests flaky when state leaks between them. Give every test its own cache, or call Cache.clear() in a setup method: class UserServiceTest { private final Cache<String, User> cache = Cache.<String, User>builder().build(); @AfterEach void reset() { cache.clear(); } } How entries move through the cache To assert on behaviour instead of internals, enable statistics and check the counters: assertThat(cache.stats().hits()).isEqualTo(1);","keywords":"","kind":"page","area":"guides"},{"url":"api/dev.example.cache.Cache.html","title":"Cache","section":"API Reference","heading":"","text":"","keywords":"memoize lookup store","kind":"interface","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-builder","title":"Cache","section":"API Reference","heading":"builder()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-get-K","title":"Cache","section":"API Reference","heading":"get()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-getOrLoad-K-Function","title":"Cache","section":"API Reference","heading":"getOrLoad()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-put-K-V","title":"Cache","section":"API Reference","heading":"put()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-invalidate-K","title":"Cache","section":"API Reference","heading":"invalidate()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-clear","title":"Cache","section":"API Reference","heading":"clear()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-size","title":"Cache","section":"API Reference","heading":"size()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.Cache.html#method-stats","title":"Cache","section":"API Reference","heading":"stats()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.CacheBuilder.html","title":"CacheBuilder","section":"API Reference","heading":"","text":"","keywords":"","kind":"class","area":"api"},{"url":"api/dev.example.cache.CacheBuilder.html#method-maximumSize-long","title":"CacheBuilder","section":"API Reference","heading":"maximumSize()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.CacheBuilder.html#method-expireAfterWrite-Duration","title":"CacheBuilder","section":"API Reference","heading":"expireAfterWrite()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.CacheBuilder.html#method-evictionPolicy-EvictionPolicy","title":"CacheBuilder","section":"API Reference","heading":"evictionPolicy()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.CacheBuilder.html#method-recordStats","title":"CacheBuilder","section":"API Reference","heading":"recordStats()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.CacheBuilder.html#method-build","title":"CacheBuilder","section":"API Reference","heading":"build()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.CacheBuilder.html#method-create","title":"CacheBuilder","section":"API Reference","heading":"create()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.EvictionPolicy.html","title":"EvictionPolicy","section":"API Reference","heading":"","text":"","keywords":"","kind":"enum","area":"api"},{"url":"api/dev.example.cache.EvictionPolicy.html#constant-LRU","title":"EvictionPolicy","section":"API Reference","heading":"LRU","text":"","keywords":"","kind":"enum constant","area":"api"},{"url":"api/dev.example.cache.EvictionPolicy.html#constant-LFU","title":"EvictionPolicy","section":"API Reference","heading":"LFU","text":"","keywords":"","kind":"enum constant","area":"api"},{"url":"api/dev.example.cache.EvictionPolicy.html#constant-FIFO","title":"EvictionPolicy","section":"API Reference","heading":"FIFO","text":"","keywords":"","kind":"enum constant","area":"api"},{"url":"api/dev.example.cache.CacheStats.html","title":"CacheStats","section":"API Reference","heading":"","text":"","keywords":"","kind":"record","area":"api"},{"url":"api/dev.example.cache.CacheStats.html#method-hitRate","title":"CacheStats","section":"API Reference","heading":"hitRate()","text":"","keywords":"","kind":"method","area":"api"},{"url":"api/dev.example.cache.CacheLoadException.html","title":"CacheLoadException","section":"API Reference","heading":"","text":"","keywords":"","kind":"class","area":"api"},{"url":"api/dev.example.cache.CacheLoadException.html#constructor-CacheLoadException-String-Throwable","title":"CacheLoadException","section":"API Reference","heading":"CacheLoadException()","text":"","keywords":"","kind":"constructor","area":"api"},{"url":"recipes/caching-http-responses.html","title":"Caching HTTP responses","section":"Recipes","heading":"","text":"This page lives in the folder docs/recipes/. The section \"Recipes\" is not declared in doctize.yml: Doctize created it automatically because a folder with that name exists. var responses = Cache.<URI, byte[]>builder() .maximumSize(200) .expireAfterWrite(Duration.ofSeconds(30)) .build(); byte[] body = responses.getOrLoad(uri, u -> client.get(u).body()); Keep the time to live short if the server sends Cache-Control: no-cache.","keywords":"","kind":"page","area":"guides"}],"version":1};
